import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Bảy câu đáng đổi cách nghĩ","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/index.md","filePath":"mental-models/index.md"}'),c={name:"mental-models/index.md"};function g(o,n,e,r,l,u){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="bay-cau-đang-đoi-cach-nghi" tabindex="-1">Bảy câu đáng đổi cách nghĩ <a class="header-anchor" href="#bay-cau-đang-đoi-cach-nghi" aria-label="Permalink to &quot;Bảy câu đáng đổi cách nghĩ&quot;">​</a></h1><p>Trên trang này# Bảy câu đáng đổi cách nghĩ <a href="#bay-cau-đang-đoi-cach-nghi">​</a> Đây là phần quan trọng nhất của Pearl. Không phải vì nội dung khó, mà vì bảy câu dưới đây chi phối gần như mọi quyết định học tập trong một gia đình — thường mà không ai nói ra. Mỗi trang giải thích một hiểu lầm, vì sao nó tồn tại (chúng đều có lý do hợp lý), và điều gì đúng hơn. <a href="/mental-models/diem-cao"><strong>Điểm cao ≠ hiểu sâu</strong>Điểm đo được nhiều thứ, và &quot;hiểu&quot; chỉ là một trong số đó. Bốn cách đạt điểm cao mà không hiểu.</a><a href="/mental-models/lam-nhieu-bai"><strong>Làm nhiều bài ≠ học tốt</strong>Bài thứ hai mươi cùng dạng gần như không dạy gì. Khối lượng là thứ dễ đo nhất và dễ gây nhầm nhất.</a><a href="/mental-models/test-khong-phan-xet"><strong>Test không phải để phán xét learner</strong>Một bài đo là câu hỏi của hệ thống, không phải bản án về đứa trẻ.</a><a href="/mental-models/uncertainty"><strong>Mọi learner model đều có uncertainty</strong>Một hệ thống dám nói &quot;tôi chưa biết&quot; đáng tin hơn hệ thống lúc nào cũng có số.</a><a href="/mental-models/cuoc-thi"><strong>Không phải cuộc thi nào cũng đáng tham gia</strong>Mỗi cuộc thi có một cái giá. Câu hỏi là nó mua được gì cho con.</a><a href="/mental-models/muc-tieu-cuoi"><strong>Mục tiêu cuối cùng không chỉ là thi đỗ</strong>Đỗ là một cánh cửa, không phải đích đến. Chuyện gì xảy ra sau khi cửa mở?</a><a href="/mental-models/portrait-vs-kpi"><strong>Student Portrait quan trọng hơn danh sách KPI</strong>Cái gì đo được sẽ được tối ưu. Đó là lý do phải cẩn thận với thứ mình chọn để đo.</a></p><h2 id="vi-sao-mental-model-quan-trong-hon-thong-tin-​" tabindex="-1">Vì sao mental model quan trọng hơn thông tin <a href="#vi-sao-mental-model-quan-trong-hon-thong-tin">​</a> <a class="header-anchor" href="#vi-sao-mental-model-quan-trong-hon-thong-tin-​" aria-label="Permalink to &quot;Vì sao mental model quan trọng hơn thông tin [​](#vi-sao-mental-model-quan-trong-hon-thong-tin)&quot;">​</a></h2><p>Bạn có thể đọc hết mọi thứ về learner model, retention, readiness — nhưng nếu trong đầu vẫn giữ niềm tin &quot;làm nhiều bài thì giỏi lên&quot;, mọi quyết định vẫn sẽ đi theo niềm tin đó. Mental model là <strong>cách hiểu ngầm</strong> về việc gì đó vận hành. Nó chạy dưới lớp ý thức, và nó quyết định hành động nhanh hơn bất kỳ lập luận nào. Đó là lý do biết một điều và hành động theo điều đó là hai chuyện khác nhau.</p><h2 id="bay-cau-nay-khong-phai-đe-phe-phan-​" tabindex="-1">Bảy câu này không phải để phê phán <a href="#bay-cau-nay-khong-phai-đe-phe-phan">​</a> <a class="header-anchor" href="#bay-cau-nay-khong-phai-đe-phe-phan-​" aria-label="Permalink to &quot;Bảy câu này không phải để phê phán [​](#bay-cau-nay-khong-phai-đe-phe-phan)&quot;">​</a></h2><p>Mọi hiểu lầm ở đây đều <strong>có lý do hợp lý</strong>. Chúng tồn tại vì:</p><ul><li>Chúng từng đúng trong một hoàn cảnh khác.</li><li>Chúng đo được thứ dễ đo, trong khi thứ quan trọng thì khó đo.</li><li>Chúng cho cảm giác kiểm soát khi mọi thứ khác đều bất định. Nuôi một đứa trẻ là việc có quá nhiều bất định. Điểm số, số lượng bài tập, thứ hạng — chúng cho một mặt đất chắc chắn để đứng lên. Không có gì đáng trách trong việc bám vào chúng. Điều Pearl đề nghị không phải là vứt bỏ chúng, mà là <strong>biết chúng đo cái gì và không đo cái gì</strong> — để chúng thôi làm thay công việc suy nghĩ. Cách đọc nhóm này Đọc từng trang một, cách nhau vài ngày. Sau mỗi trang, thử để ý xem trong tuần đó bạn ra quyết định nào dựa trên đúng cái hiểu lầm vừa đọc. Đó là bài tập khó chịu, và nó có tác dụng hơn hẳn việc đọc một mạch cả bảy trang. Nemo12 không chỉ dạy trẻ. Khi cả gia đình hiểu đúng về việc học, những quyết định quan trọng nhất — vốn được ra ở nhà, không phải trong ứng dụng — cũng tốt lên.</li></ul>',7)])])}const d=h(c,[["render",g]]);export{s as __pageData,d as default};
